#!/usr/bin/env python3
"""
Round 163h (culprits), 4 October 2026. Needs round 162m.

Hell place names; notes beside Woodlands and Old fantasy painting.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ['## Round 163h (4 October)\n\nNeeds round 162m (guards on its heading). No tiles patch. No app.js?v= bump.\nMade in the Hell chat ("h"); it touches only its own blocks and adds one.\n\n- Hell\'s place names in its own theme (asked: "the place names should be in\n  the same theme"). CARTO\'s picture of names is hidden on Hell (namesRaster\n  wrapped) and names are drawn from OpenFreeMap\'s place, water_name,\n  waterway, mountain_peak and transportation_name in EB Garamond (the 162b\n  letter files in map/glyphs): countries in spaced SemiBold capitals of dull\n  blood red (#A9504C), states italic capitals, cities and towns ash (#CDBDB4,\n  #B4A39B), seas, lakes and rivers italic dark rose (#B0605F), black halos\n  (HELL_NAME, HELL_NAME_IDS outline-hell-name-*, hellNameLayers,\n  addHellNames, hellNamesOnTop). Glyphs set only if none are set; if the\n  map\'s letters come from elsewhere (HELL_GLYPHS false), the picture of names\n  stays, turned light on dark as before. Names off in the Place names box stay\n  off when the layers are first added.\n- Notes beside two painted basemaps, as Mother Earth has (162m): an (i)\n  beside Woodlands and beside Old fantasy painting (data-bm-note, BM_NOTES,\n  #bm-note, CSS #bm-note-css). Old fantasy painting\'s is laid out like a card\n  (name bar, type line "Basemap - The Painted Earth", what it shows, flavour\n  text over a rule), in the spirit of Magic: The Gathering\'s 1990s card art and\n  flavour text. Woodlands\' reads like a painting\'s caption, in the spirit of\n  Robert Griffing: the eastern forests as the homelands of the Haudenosaunee,\n  Lenape, Shawnee and other nations, kept open with fire, almost all the old\n  forest cut by the end of the 1800s. Both say nothing is copied. One block\n  ("Notes beside the painted basemaps" to its end) after Mother Earth\'s;\n  Mother Earth\'s (i) (data-bm-info) is untouched.\n- Waiting on the owner: who "Carl-August W." is, and which basemap the note\n  in the spirit of Nusantara Atlas and Carl-August W. belongs to.\n- Checked: layers pass the style-spec validator; panel buttons in the test\n  run. Not seen against live tiles.\n']


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round163h: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 162m" not in h.read_text(encoding="utf-8"):
        sys.exit("round163h: round 162m must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round163h: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("round163h: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round163h: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


DIFF = ''

if __name__ == "__main__":
    main()
